package com.quizarena.client;

import javafx.application.Application;
import javafx.application.Platform;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Node;
import javafx.scene.Scene;
import javafx.scene.chart.PieChart;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Rectangle;
import javafx.scene.shape.Polyline;
import javafx.stage.Stage;
import javafx.stage.StageStyle;

/** The complete QuizArena client. JavaFX is the primary UI toolkit. */
public class QuizClient extends Application {
    private static final String INK="#4e3325", PAPER="#f6ebdd", CREAM="#fff9f1", LINE="#d6bea6", BROWN="#6f4933", TERRACOTTA="#b1704b";
    private Stage stage; private BorderPane root; private ServerConnection connection; private String role="PLAYER";
    private long questionId; private boolean answered; private Label questionLabel; private VBox options;
    private TextArea boardText, analysisText; private PieChart chart;
    @Override public void start(Stage s){stage=s;stage.initStyle(StageStyle.DECORATED);stage.setTitle("QuizArena");stage.setWidth(1200);stage.setHeight(800);stage.setMinWidth(900);stage.setMinHeight(650);stage.setResizable(true);showWelcome();stage.show();stage.centerOnScreen();}
    private void showWelcome(){VBox b=box(22);b.setAlignment(Pos.CENTER);b.getChildren().addAll(robot(),text("QUIZARENA",38,true),text("A warm pixel-inspired multiplayer quiz world",18,false),buttonAction("GET STARTED",e->showAuthChoice()),buttonAction("HOW TO PLAY",e->showHelp(false)));setPage("QUIZARENA","Play, compete, and make every answer count",b);}
    private void showAuthChoice(){HBox h=new HBox(24,authCard("SIGN IN","Already have an account? Jump back into your rooms and scores.",e->showLogin()),authCard("REGISTER","Create a player account and start your first quiz.",e->showRegister()));h.setAlignment(Pos.CENTER);setPage("WELCOME TO QUIZARENA","Choose how you want to enter the arena",h,buttonAction("BACK",e->showWelcome()));}
    private VBox authCard(String title,String copy,javafx.event.EventHandler<javafx.event.ActionEvent> action){VBox v=card();v.setPrefWidth(330);v.getChildren().addAll(text(title,25,true),text(copy,15,false),buttonAction(title.equals("SIGN IN")?"SIGN IN":"CREATE ACCOUNT",action));return v;}
    private void showLogin(){TextField email=new TextField();PasswordField pass=new PasswordField();style(email);style(pass);VBox f=card();f.setPrefWidth(680);f.setMaxWidth(760);f.getChildren().addAll(text("SIGN IN",26,true),field("EMAIL",email),field("PASSWORD",pass),buttonAction("SIGN IN",e->{try{connect();connection.send("AUTH|"+email.getText().trim()+"|"+pass.getText());}catch(Exception x){error(x);}}),buttonAction("REGISTER INSTEAD",e->showRegister()));HBox h=new HBox(90,robot(),f);h.setAlignment(Pos.CENTER);setPage("SIGN IN","Welcome back, player",h,buttonAction("BACK",e->showAuthChoice()));}
    private void showRegister(){TextField user=new TextField(),email=new TextField();PasswordField pass=new PasswordField();for(Control c:new Control[]{user,email,pass})style(c);VBox f=card();f.setMaxWidth(560);f.getChildren().addAll(text("CREATE PLAYER ACCOUNT",26,true),field("USERNAME",user),field("EMAIL",email),field("PASSWORD",pass),buttonAction("CREATE ACCOUNT",e->{try{connect();connection.send("REGISTER|"+user.getText().trim()+"|"+email.getText().trim()+"|"+pass.getText());}catch(Exception x){error(x);}}),buttonAction("BACK TO SIGN IN",e->showLogin()));setPage("REGISTER","Create your player account",f,buttonAction("BACK",e->showAuthChoice()));}
    private void showDashboard(){HBox nav=new HBox(10);nav.setAlignment(Pos.CENTER_LEFT);Button play=button("PLAY / ROOMS"),board=button("LIVE LEADERBOARD"),analysis=button("MY ANALYSIS"),help=button("HOW TO PLAY"),out=button("SIGN OUT");nav.getChildren().addAll(play,board,analysis,help);if("ADMIN".equals(role))nav.getChildren().add(buttonAction("ADMIN: ADD QUESTION",e->adminQuestion()));nav.getChildren().add(out);StackPane content=new StackPane();VBox rooms=rooms();boardText=new TextArea("No completed quizzes yet.");boardText.setEditable(false);styleArea(boardText);VBox leader=card();leader.getChildren().addAll(text("LEADERBOARD",25,true),boardText);VBox ana=analysis();content.getChildren().add(rooms);play.setOnAction(e->content.getChildren().setAll(rooms));board.setOnAction(e->{content.getChildren().setAll(leader);send("GLOBAL");});analysis.setOnAction(e->{content.getChildren().setAll(ana);send("ANALYSIS");});help.setOnAction(e->showHelp(true));out.setOnAction(e->signOut(true));VBox page=box(18);page.getChildren().addAll(nav,content);VBox.setVgrow(content,Priority.ALWAYS);setPage("DASHBOARD","Your arena home",page);}
    private VBox rooms(){HBox split=new HBox(18);VBox create=card(),join=card();create.getChildren().addAll(text("CREATE A ROOM",23,true),text("Host a quiz for friends",14,false));TextField cat=new TextField("Java Programming"),diff=new TextField("EASY"),count=new TextField("5"),seconds=new TextField("15"),max=new TextField("8");for(TextField f:new TextField[]{cat,diff,count,seconds,max})style(f);create.getChildren().addAll(field("CATEGORY",cat),field("DIFFICULTY",diff),field("QUESTIONS",count),field("SECONDS / QUESTION",seconds),field("MAX PLAYERS",max),buttonAction("CREATE ROOM",e->send("CREATE|host|"+cat.getText()+"|"+diff.getText()+"|"+count.getText()+"|"+seconds.getText()+"|"+max.getText())),buttonAction("START MY ROOM",e->send("START")));TextField code=new TextField();style(code);join.getChildren().addAll(text("JOIN A ROOM",23,true),text("Enter the six-digit code shared by the host",14,false),field("ROOM CODE",code),buttonAction("JOIN ROOM",e->send("JOIN|"+code.getText().trim())),text("Wait in the lobby until the host starts.",13,false));split.getChildren().addAll(create,join);HBox.setHgrow(create,Priority.ALWAYS);HBox.setHgrow(join,Priority.ALWAYS);VBox v=box(12);v.getChildren().add(split);return v;}
    private VBox analysis(){analysisText=new TextArea("Complete a quiz to see your question-by-question analysis.");analysisText.setEditable(false);styleArea(analysisText);chart=new PieChart();chart.setTitle("Correct vs wrong");chart.setLegendVisible(true);chart.setPrefWidth(330);VBox v=box(12);HBox h=new HBox(16,analysisText,chart);HBox.setHgrow(analysisText,Priority.ALWAYS);v.getChildren().addAll(text("MY QUIZ ANALYSIS",24,true),h);return v;}
    private void showQuiz(){questionLabel=text("Waiting for the next question...",24,true);options=new VBox(12);VBox p=box(24);p.getChildren().addAll(text("LIVE QUIZ",32,true),text("Choose one answer before the timer expires.",16,false),questionLabel,options);setPage("LIVE QUIZ","Your answer locks after selection",p);}
    private void showHelp(boolean dashboard){TextArea t=new TextArea("GETTING STARTED\n1. Sign in or register a player account.\n2. Open PLAY / ROOMS from your dashboard.\n\nCREATE A ROOM\n• Enter category, difficulty, question count, time limit, and player limit.\n• Choose CREATE ROOM and share the code.\n• Choose START MY ROOM when everyone has joined.\n\nJOIN A ROOM\n• Enter the host's six-digit room code and choose JOIN ROOM.\n• Wait for the host to start.\n\nDURING THE QUIZ\n• Select one answer. It locks immediately.\n• Open LIVE LEADERBOARD to see current rankings.\n\nAFTER THE QUIZ\n• Open MY ANALYSIS to see every correct and wrong answer and your accuracy chart.\n• Use SIGN OUT when finished. Back buttons only navigate.");t.setEditable(false);t.setWrapText(true);styleArea(t);setPage("HOW TO PLAY","Player instructions",t,buttonAction("BACK",e->{if(dashboard)showDashboard();else showWelcome();}));}
    private void adminQuestion(){Dialog<ButtonType>d=new Dialog<>();d.setTitle("Add question");GridPane g=new GridPane();g.setHgap(8);g.setVgap(8);g.setPadding(new Insets(15));String[] n={"Category","Difficulty","Question","Option A","Option B","Option C","Option D","Correct (A-D)"};TextField[] f=new TextField[8];for(int i=0;i<8;i++){f[i]=new TextField(i==0?"Java Programming":i==1?"EASY":"");style(f[i]);g.add(new Label(n[i]),0,i);g.add(f[i],1,i);}d.getDialogPane().setContent(g);d.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);if(d.showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK){StringBuilder s=new StringBuilder("ADMIN_ADD");for(TextField x:f)s.append('|').append(x.getText());send(s.toString());}}
    private void handle(String line){Platform.runLater(()->{String[]p=line.split("\\|",-1);try{switch(p[0]){case"AUTH_OK"->{role=p.length>2?p[2]:"PLAYER";stage.setTitle("QuizArena - "+role);showDashboard();}case"REGISTERED"->{info("Account created. Sign in to enter the arena.");showLogin();}case"JOINED"->info("Joined room "+p[1]+". Wait for the host to start.");case"QUESTION"->{showQuiz();answered=false;questionId=Long.parseLong(p[4]);questionLabel.setText("Q"+(Integer.parseInt(p[1])+1)+" / "+p[2]+"    "+p[5]);for(int i=0;i<4;i++){char a=(char)('A'+i);Button b=button(a+"  "+p[6+i]);b.setOnAction(e->{if(!answered){answered=true;options.getChildren().forEach(n->n.setDisable(true));b.setText("SUBMITTED");send("ANSWER|"+questionId+"|"+a+"|0");}});options.getChildren().add(b);}}case"GLOBAL"->{if(boardText!=null)boardText.setText("GLOBAL LEADERBOARD\n\n"+formatGlobal(p.length>1?p[1]:""));}case"ANALYSIS"->{if(analysisText!=null)analysisText.setText(formatAnalysis(p.length>1?p[1]:""));}case"ANALYSIS_TOTAL"->{if(chart!=null)chart.setData(javafx.collections.FXCollections.observableArrayList(new PieChart.Data("Correct",Integer.parseInt(p[1])),new PieChart.Data("Wrong",Integer.parseInt(p[2]))));}case"FINISHED"->{showDashboard();info("Quiz finished. Open MY ANALYSIS to review your answers.");}case"ADMIN_OK"->info("Question added to the question bank.");case"ERROR"->error(new RuntimeException(p.length>1?p[1]:"Unknown server error"));}}catch(Exception x){error(x);}});}
    private String formatGlobal(String raw){if(raw.isBlank())return"No completed quizzes yet.";StringBuilder s=new StringBuilder("PLAYER                         SCORE   CORRECT\n\n");for(String row:raw.split(";")){String[]x=row.split(",");if(x.length>=4)s.append(String.format("%-30s %-7s %-9s%n",x[0],x[1],x[2]));}return s.toString();}
    private String formatAnalysis(String raw){if(raw.isBlank())return"No completed quiz analysis yet.";StringBuilder s=new StringBuilder("LATEST QUIZ REVIEW\n\n");for(String row:raw.split(";")){String[]x=row.split("\\|",-1);if(x.length>=4)s.append("CORRECT".equals(x[3])?"RIGHT  ":"WRONG  ").append(x[0]).append("\nYour answer: ").append(x[1]).append("   Correct: ").append(x[2]).append("\n\n");}return s.toString();}
    private void connect()throws Exception{if(connection==null)connection=new ServerConnection(env("QUIZ_SERVER_HOST","localhost"),Integer.parseInt(env("QUIZ_SERVER_PORT","5050")),this::handle);}
    private void send(String s){if(connection==null){error(new RuntimeException("Sign in first."));return;}connection.send(s);}
    private void signOut(boolean ask){if(ask&&new Alert(Alert.AlertType.CONFIRMATION,"Sign out of this QuizArena session?").showAndWait().orElse(ButtonType.NO)!=ButtonType.OK)return;try{if(connection!=null)connection.close();}catch(Exception ignored){}connection=null;role="PLAYER";answered=false;stage.setTitle("QuizArena");showWelcome();}
    private void setPage(String title,String subtitle,Node content,Button...footer){root=new BorderPane();root.setPadding(new Insets(18,28,28,28));root.setStyle("-fx-background-color:"+PAPER+";");VBox heading=box(4);heading.getChildren().addAll(text(title,34,true),text(subtitle,16,false));root.setTop(heading);ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setStyle("-fx-background:#f6ebdd; -fx-background-color:#f6ebdd;");root.setCenter(scroll);if(footer.length>0)root.setBottom(new HBox(10,footer));stage.setScene(new Scene(root,stage.getWidth(),stage.getHeight()));}
    private VBox box(double gap){VBox v=new VBox(gap);v.setPadding(new Insets(16));return v;}private VBox card(){VBox v=box(14);v.setPadding(new Insets(24));v.setStyle("-fx-background-color:"+CREAM+"; -fx-border-color:"+LINE+"; -fx-border-width:2;");return v;}private HBox field(String name,Control c){Label l=new Label(name);l.setTextFill(Color.web(INK));l.setMinWidth(190);HBox h=new HBox(24,l,c);h.setAlignment(Pos.CENTER_LEFT);HBox.setHgrow(c,Priority.ALWAYS);c.setPrefWidth(420);return h;}
    private Button button(String s){return buttonAction(s,e->{});}private Button buttonAction(String s,javafx.event.EventHandler<javafx.event.ActionEvent>h){Button b=new Button(s);b.setOnAction(h);b.setMaxWidth(Double.MAX_VALUE);b.setStyle("-fx-background-color:"+BROWN+"; -fx-text-fill:"+CREAM+"; -fx-font-family:'Monospaced'; -fx-font-weight:bold; -fx-padding:13 18;");return b;}private Label text(String s,int z,boolean bold){Label l=new Label(s);l.setTextFill(Color.web(INK));l.setStyle("-fx-font-family:'Monospaced'; -fx-font-size:"+z+"px; -fx-font-weight:"+(bold?"bold":"normal")+";");l.setWrapText(true);return l;}private void style(Control c){c.setStyle("-fx-background-color:"+CREAM+"; -fx-border-color:"+LINE+"; -fx-padding:10; -fx-font-family:'Monospaced'; -fx-font-size:14px;");}private void styleArea(TextArea a){style(a);a.setWrapText(true);a.setPrefRowCount(16);}
    private Pane robot(){Pane p=new Pane();p.setPrefSize(290,250);Rectangle b=new Rectangle(50,45,190,150);b.setArcWidth(18);b.setArcHeight(18);b.setFill(Color.web(TERRACOTTA));Rectangle screen=new Rectangle(70,68,150,85);screen.setFill(Color.web("#487c70"));Circle l=new Circle(105,105,7,Color.web(CREAM)),r=new Circle(185,105,7,Color.web(CREAM));Polyline smile=new Polyline(125,122,125,132,135,140,155,140,165,132,165,122);smile.setStroke(Color.web("#f7d65e"));smile.setStrokeWidth(6);smile.setFill(Color.TRANSPARENT);p.getChildren().addAll(b,screen,l,r,smile);return p;}
    private static String env(String n,String d){String v=System.getenv(n);return v==null||v.isBlank()?d:v;}private void info(String s){new Alert(Alert.AlertType.INFORMATION,s).showAndWait();}private void error(Exception e){new Alert(Alert.AlertType.ERROR,e.getMessage()==null?e.toString():e.getMessage()).showAndWait();}@Override public void stop(){try{if(connection!=null)connection.close();}catch(Exception ignored){}}public static void main(String[]a){launch(a);}
}
